#include "boot_startup.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static tf_model memory;
static bs_model m;
static rc_adapter candidate;
static uint8_t boot[12288];
static unsigned checks,failures,groups;
static bs_request log_items[2048];
static unsigned log_count,hal_fail_at,clock_count,alloc_calls,free_calls,rom_calls;
static uint32_t allocation,last_size,last_free,clocks[8],clock_length;
static int alloc_known,free_known,rom_known,rom_value,uart_ready;
static int mutate_clock,mutate_uart,callback_mutate;
static bs_flow jump_flow;
static uint32_t app_byte;
static int app_known;
#define A(x) (TF_RAM_BASE+UINT32_C(x))
#define CHECK(x) do {checks++;if(!(x)){failures++;printf("FAIL line=%d %s\n",__LINE__,#x);}} while(0)
static void group(const char *s){groups++;printf("GROUP %s\n",s);}
static void put(uint32_t a,uint32_t v,unsigned n){unsigned i;for(i=0;i<n;i++){memory.ram[a-TF_RAM_BASE+i]=(uint8_t)(v>>(8*i));memory.known[a-TF_RAM_BASE+i]=255;}}
static uint32_t get(uint32_t a,unsigned n){unsigned i;uint32_t v=0;for(i=0;i<n;i++)v|=(uint32_t)memory.ram[a-TF_RAM_BASE+i]<<(8*i);return v;}
static int allocate(void *p,uint32_t size,uint32_t *out){(void)p;alloc_calls++;last_size=size;if(!alloc_known)return 0;*out=allocation;return 1;}
static int release(void *p,uint32_t a){(void)p;free_calls++;last_free=a;return free_known;}
static int rom(void *p,unsigned off,uint8_t task,uint16_t mask,uint32_t ticks){bs_request q;(void)p;memset(&q,0,sizeof(q));q.operation=BS_CALLBACK;q.va=off;q.address=task;q.value=mask;q.argument=ticks;if(log_count<2048)log_items[log_count++]=q;rom_calls++;return rom_known?rom_value:TF_UNKNOWN;}
static bs_flow hal(void *p,bs_model *q,const bs_request *r,bs_result *v){
    (void)p;CHECK(q==&m);if(log_count<2048)log_items[log_count++]=*r;
    if(hal_fail_at&&log_count==hal_fail_at)return BS_HALT;
    v->known=UINT32_MAX;v->value=0;
    if(r->operation==BS_MMIO_READ){
        if(r->address==0x40000400)v->value=0x0122;
        else if(r->address==0x40000410)v->value=0x0015;
        else if(r->address==0x4001080c)v->value=0x11223340;
        else if(r->address==0x40004400)v->value=uart_ready?0x40u:0u;
    }
    if(r->operation==BS_CLOCK){v->value=clock_count<clock_length?clocks[clock_count]:100;clock_count++;if(mutate_clock==1||(mutate_clock==2&&clock_count==2)){put(A(0x9586),1,1);put(A(0x9588),9,2);mutate_clock=0;}}
    if(r->operation==BS_CALLBACK&&callback_mutate){put(A(0x9585),7,1);callback_mutate=0;}
    if(r->operation==BS_MMIO_WRITE&&r->address==0x40004404&&(mutate_uart==1||(mutate_uart==2&&r->value==3))){put(A(0x6000),7,1);mutate_uart=0;}
    if(r->operation==BS_JUMP)return jump_flow;
    if(r->operation==BS_MEMORY_READ&&r->address==0x8000){v->value=app_byte;v->known=app_known?UINT32_MAX:0;}
    if(r->operation==BS_RESET_WAIT)return BS_TRANSFER;
    return BS_RETURNED;
}
static void fresh(void){bs_backend b;memset(&memory,0,sizeof(memory));memset(memory.ram,0xa7,sizeof(memory.ram));memset(memory.known,255,sizeof(memory.known));memset(&b,0,sizeof(b));b.msg_allocate=allocate;b.msg_deallocate=release;b.rom_status=rom;b.hal=hal;bs_init(&m,&memory,&b);put(A(0x9590),0,4);put(A(0x958c),0,4);put(A(0x408d),4,1);log_count=hal_fail_at=clock_count=alloc_calls=free_calls=rom_calls=0;allocation=A(0x6000);last_size=last_free=clock_length=0;alloc_known=free_known=rom_known=uart_ready=1;rom_value=0;mutate_clock=mutate_uart=callback_mutate=0;jump_flow=BS_TRANSFER;app_byte=0x6f;app_known=1;}
static unsigned writes(uint32_t address){unsigned i,n=0;for(i=0;i<log_count;i++)if(log_items[i].operation==BS_MMIO_WRITE&&log_items[i].address==address)n++;return n;}
static uint32_t last_write(uint32_t address){unsigned i=log_count;while(i--)if(log_items[i].operation==BS_MMIO_WRITE&&log_items[i].address==address)return log_items[i].value;return UINT32_MAX;}
static void records(uint32_t p,uint16_t frequency,uint16_t on,uint16_t off){put(p,frequency,2);put(p+2,on,2);put(p+4,off,2);}
static void phase(uint8_t p){put(A(0x9580),0,4);put(A(0x9585),p,1);put(A(0x9586),0,1);put(A(0x9590),A(0x6000),4);records(A(0x6000),3000,40,80);records(A(0x6006),0,0,0);}
static void test_pattern(void){unsigned i;group("pattern6B, untouched sentinel tail and raw32 >19 branch");fresh();CHECK(bs_pattern(&m,3)==BS_RETURNED);CHECK(last_size==24);CHECK(get(A(0x9590),4)==A(0x6000));for(i=0;i<3;i++){CHECK(get(A(0x6000)+6*i,2)==3000);CHECK(get(A(0x6002)+6*i,2)==40);CHECK(get(A(0x6004)+6*i,2)==80);}CHECK(get(A(0x6012),2)==0);CHECK(get(A(0x6014),2)==0xa7a7);CHECK(get(A(0x9580),4)==0);CHECK(get(A(0x9585),1)==0&&get(A(0x9586),1)==0);CHECK(writes(0x40000424)==1&&last_write(0x40000400)==0x123);fresh();CHECK(bs_pattern(&m,0)==BS_RETURNED);CHECK(last_size==6&&get(A(0x6000),2)==0&&get(A(0x6002),2)==0xa7a7);fresh();CHECK(bs_pattern(&m,UINT32_MAX)==BS_RETURNED);CHECK(last_size==12&&get(A(0x6000),2)==3000&&get(A(0x6002),2)==65535);CHECK(get(A(0x6004),2)==0&&get(A(0x6006),2)==0&&get(A(0x6008),2)==0xa7a7);}
static void test_configure(void){uint32_t out=9;group("replace/free prefix, raw multiplication, NULL and missing calls");fresh();put(A(0x9590),A(0x7000),4);put(A(0x958c),0x1234,4);CHECK(bs_configure(&m,UINT32_MAX,&out)==BS_RETURNED);CHECK(free_calls==1&&last_free==A(0x7000));CHECK(last_size==0xfffffffa&&out==A(0x6000));CHECK(get(A(0x9590),4)==0&&get(A(0x958c),4)==0);CHECK(last_write(0x4000042c)==65535&&last_write(0x4000043c)==0&&last_write(0x40000400)==0x122);fresh();put(A(0x9590),A(0x7000),4);free_known=0;CHECK(bs_pattern(&m,2)==BS_HALT);CHECK(get(A(0x9590),4)==A(0x7000)&&alloc_calls==0);fresh();allocation=0;CHECK(bs_pattern(&m,1)==BS_RETURNED);CHECK(get(A(0x9590),4)==0&&log_count==0);fresh();m.backend.msg_allocate=NULL;CHECK(bs_pattern(&m,1)==BS_HALT&&get(A(0x9590),4)==0);fresh();put(A(0x9590),A(0x7000),4);hal_fail_at=2;CHECK(bs_pattern(&m,2)==BS_HALT);CHECK(get(A(0x9590),4)==0&&get(A(0x958c),4)==0&&alloc_calls==0);}
static void test_irq_phase0(void){group("IRQ clears flag before clock; phase0 reload and live index");fresh();phase(0);CHECK(bs_pattern_irq(&m)==BS_RETURNED);CHECK(last_write(0x40000410)==0x14&&last_write(0x4000042c)==332&&last_write(0x4000043c)==200);CHECK(get(A(0x9580),4)==140&&get(A(0x9585),1)==1&&clock_count==2);fresh();phase(0);records(A(0x6000),0,2,3);CHECK(bs_pattern_irq(&m)==BS_RETURNED);CHECK(last_write(0x4000042c)==65534);fresh();phase(0);records(A(0x6006),4000,7,9);mutate_clock=1;CHECK(bs_pattern_irq(&m)==BS_RETURNED);CHECK(last_write(0x4000042c)==249&&get(A(0x9580),4)==107);}
static void test_irq_phase1(void){group("phase1 off gap, unsigned deadline and unknown operands");fresh();phase(1);clocks[0]=100;clocks[1]=UINT32_MAX-20;clock_length=2;CHECK(bs_pattern_irq(&m)==BS_RETURNED);CHECK(last_write(0x4000043c)==0&&get(A(0x9580),4)==59&&get(A(0x9585),1)==2);fresh();phase(0);put(A(0x9580),101,4);memory.known[0x9585]=0;CHECK(bs_pattern_irq(&m)==BS_RETURNED&&clock_count==1&&writes(0x4000042c)==0);fresh();phase(0);memory.known[0x6000]=0;CHECK(bs_pattern_irq(&m)==BS_HALT);CHECK(last_write(0x40000410)==0x14&&writes(0x4000042c)==0&&get(A(0x9585),1)==0);}
static void test_irq_phase2(void){group("phase2 deferred free, sentinel, hold and no repeated allocation");fresh();phase(2);put(A(0x9588),0,2);CHECK(bs_pattern_irq(&m)==BS_RETURNED);CHECK(get(A(0x9586),1)==1&&get(A(0x9590),4)==0&&free_calls==1);CHECK(get(A(0x9585),1)==2&&last_write(0x40000400)==0x122);fresh();phase(2);records(A(0x6006),1000,1,2);CHECK(bs_pattern_irq(&m)==BS_RETURNED);CHECK(get(A(0x9585),1)==0&&free_calls==0&&get(A(0x9590),4)==A(0x6000));fresh();phase(2);put(A(0x9588),8,2);CHECK(bs_pattern_irq(&m)==BS_RETURNED);CHECK(get(A(0x9580),4)==108&&get(A(0x9588),2)==0&&get(A(0x9585),1)==3);fresh();phase(2);free_known=0;CHECK(bs_pattern_irq(&m)==BS_HALT);CHECK(get(A(0x9586),1)==1&&get(A(0x9590),4)==A(0x6000));}
static void test_irq_phase3(void){group("phase3 clears callback before invocation and preserves failed prefix");fresh();phase(3);put(A(0x958c),0x12345678,4);callback_mutate=1;CHECK(bs_pattern_irq(&m)==BS_RETURNED);CHECK(get(A(0x958c),4)==0&&get(A(0x9585),1)==0);CHECK(log_count&&log_items[log_count-1].operation==BS_CALLBACK&&log_items[log_count-1].address==0x12345678);fresh();phase(3);put(A(0x958c),0x12345678,4);hal_fail_at=9;CHECK(bs_pattern_irq(&m)==BS_HALT);CHECK(get(A(0x958c),4)==0&&get(A(0x9585),1)==3);fresh();phase(9);CHECK(bs_pattern_irq(&m)==BS_RETURNED&&get(A(0x9585),1)==9&&clock_count==1);}
static void test_task(void){uint16_t out=0;group("startup1/8/2/4 priority and exact HAL/ROM order");fresh();CHECK(bs_startup_dispatch(&m,15,&out)==BS_RETURNED&&out==14);CHECK(log_items[0].address==0x4001080c&&log_items[1].value==0x11223342);CHECK(log_items[2].va==88&&log_items[2].address==4&&log_items[2].value==1&&log_items[2].argument==160);fresh();CHECK(bs_startup_dispatch(&m,10,&out)==BS_RETURNED&&out==2);CHECK(writes(0x40004404)==6&&last_write(0x40004404)==65&&get(A(0x999b),1)==65);fresh();CHECK(bs_startup_dispatch(&m,6,&out)==BS_TRANSFER&&out==6);CHECK(log_items[0].operation==BS_JUMP&&log_items[0].address==0x8000);fresh();jump_flow=BS_RETURNED;CHECK(bs_startup_dispatch(&m,2,&out)==BS_RETURNED&&out==0);fresh();CHECK(bs_startup_dispatch(&m,4,&out)==BS_TRANSFER&&out==4);CHECK(log_items[0].operation==BS_CSR_CLEAR&&log_items[0].address==0x800&&log_items[0].value==136);CHECK(log_items[1].operation==BS_MMIO_WRITE&&log_items[1].address==0xe000e048&&log_items[1].value==0xbeef0080);fresh();CHECK(bs_startup_dispatch(&m,0x8000,&out)==BS_RETURNED&&out==0);}
static void test_stay(void){group("stay flag precedes stop/set/pattern and unchecked ROM scalar");fresh();rom_value=6;CHECK(bs_stay(&m)==BS_RETURNED);CHECK(get(A(0x408c),1)==1&&rom_calls==2&&last_size==24);CHECK(log_items[0].va==92&&log_items[0].value==2);CHECK(log_items[1].va==80&&log_items[1].value==1);fresh();rom_known=0;CHECK(bs_stay(&m)==BS_HALT&&get(A(0x408c),1)==1&&alloc_calls==0);fresh();m.backend.hal=NULL;CHECK(bs_stay(&m)==BS_HALT);CHECK(get(A(0x408c),1)==1&&get(A(0x9590),4)==A(0x6000));}
static void test_uart(void){unsigned i,n=0;uint32_t values[8]={0};group("UART frame checksum rereads payload after HAL and budget is boundary");fresh();put(A(0x6000),3,1);mutate_uart=1;CHECK(bs_uart_reply(&m,0x41,A(0x6000),1)==BS_RETURNED);for(i=0;i<log_count;i++)if(log_items[i].operation==BS_MMIO_WRITE&&log_items[i].address==0x40004404&&n<8)values[n++]=log_items[i].value;CHECK(n==7);CHECK(values[0]==85&&values[1]==127&&values[2]==65&&values[3]==0&&values[4]==1&&values[5]==7&&values[6]==73);CHECK(get(A(0x999b),1)==73);fresh();uart_ready=0;m.poll_budget=3;CHECK(bs_uart_reply(&m,65,0,0)==BS_HALT);CHECK(writes(0x40004404)==0&&get(A(0x999b),1)==0);fresh();memory.known[0x6000]=0;CHECK(bs_uart_reply(&m,65,A(0x6000),1)==BS_HALT);CHECK(writes(0x40004404)==5&&get(A(0x999b),1)==66);}
static void test_candidate(void){bs_backend b;rc_hooks hooks;uint32_t result=0;group("opt-in same SRAM candidate allocation/free and profile refusal");fresh();memset(&hooks,0,sizeof(hooks));CHECK(rc_attach(&candidate,&memory,RC_WCH_64BE955_V130,&hooks)==1);put(A(0x418c),0,1);CHECK(rc_prepare(&candidate,A(0x40a4),0x5000,2)==1);CHECK(bs_attach_candidate(&m,&candidate)==1);CHECK(bs_pattern(&m,3)==BS_RETURNED);CHECK(get(A(0x9590),4)!=0&&last_size==0);CHECK(rc_msg_deallocate(&candidate,get(A(0x9590),4),&result)==1&&result==0);memset(&b,0,sizeof(b));bs_init(&m,&memory,&b);candidate.profile=RC_PHYSICAL_UNKNOWN;CHECK(bs_attach_candidate(&m,&candidate)==0);}
static void test_policy(void){group("25EC policy tail short circuit, stay flag, raw result and image byte");fresh();put(A(0x408c),0,1);app_known=0;CHECK(bs_startup_policy_tail(&m,2)==BS_RETURNED&&alloc_calls==1);CHECK(log_items[0].va==92);fresh();memory.known[0x408c]=0;CHECK(bs_startup_policy_tail(&m,0)==BS_RETURNED);CHECK(rom_calls==1&&log_items[1].va==88&&log_items[1].value==2&&log_items[1].argument==320);fresh();put(A(0x408c),1,1);app_byte=0;CHECK(bs_startup_policy_tail(&m,0)==BS_RETURNED&&alloc_calls==0&&rom_calls==0);fresh();put(A(0x408c),0,1);app_byte=0;CHECK(bs_startup_policy_tail(&m,0)==BS_RETURNED&&alloc_calls==1);fresh();app_known=0;CHECK(bs_startup_policy_tail(&m,0x10002)==BS_HALT&&alloc_calls==0);}
static void test_live_rereads(void){unsigned i,n=0;uint32_t values[8]={0};group("second clock/payload-postsend live rereads and NULL old-pointer skip");fresh();phase(0);records(A(0x6006),4000,7,9);mutate_clock=2;CHECK(bs_pattern_irq(&m)==BS_RETURNED);CHECK(last_write(0x4000042c)==332&&get(A(0x9580),4)==107);fresh();put(A(0x6000),3,1);mutate_uart=2;CHECK(bs_uart_reply(&m,65,A(0x6000),1)==BS_RETURNED);for(i=0;i<log_count;i++)if(log_items[i].operation==BS_MMIO_WRITE&&log_items[i].address==0x40004404&&n<8)values[n++]=log_items[i].value;CHECK(n==7&&values[5]==3&&values[6]==73&&get(A(0x6000),1)==7);fresh();put(A(0x958c),0x1234,4);allocation=0;CHECK(bs_pattern(&m,3)==BS_RETURNED&&get(A(0x958c),4)==0x1234&&free_calls==0&&log_count==0);fresh();phase(2);put(A(0x9586),255,1);CHECK(bs_pattern_irq(&m)==BS_RETURNED&&get(A(0x9586),1)==0&&get(A(0x9585),1)==0&&free_calls==0);}
static void test_sources(void){group("immutable BOOT literal original-byte fixtures");CHECK(boot[0xd60]==0x63&&boot[0xd63]==0x04);CHECK(boot[0x14ae]==0x93&&boot[0x14b1]==0x00);CHECK(boot[0xcfc]==0x83&&boot[0xd0a]==0x23);CHECK(boot[0xff6]==0x93&&boot[0x100a]==0x3c);CHECK(boot[0x1aa0]==0x2a&&boot[0x1ab8]==0x19);}
int main(int argc,char **argv){FILE *f;if(argc!=2)return 2;f=fopen(argv[1],"rb");if(!f||fread(boot,1,sizeof(boot),f)!=sizeof(boot)){if(f)fclose(f);return 2;}fclose(f);test_pattern();test_configure();test_irq_phase0();test_irq_phase1();test_irq_phase2();test_irq_phase3();test_task();test_stay();test_uart();test_candidate();test_policy();test_live_rereads();test_sources();printf("BOOT_STARTUP_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no\n",groups,checks,failures);return failures?1:0;}
